enum OrderStatus {
    PLACED, PROCESSING, SHIPPED, DELIVERED, CANCELLED;

    boolean canTransitionTo(OrderStatus next) {
        return switch (this) {
            case PLACED -> next == PROCESSING || next == CANCELLED;
            case PROCESSING -> next == SHIPPED || next == CANCELLED;
            case SHIPPED -> next == DELIVERED;
            case DELIVERED, CANCELLED -> false;
        };
    }
}

OrderStatus status = OrderStatus.PLACED;
OrderStatus[] path = { OrderStatus.PROCESSING, OrderStatus.SHIPPED, OrderStatus.DELIVERED };
for (OrderStatus next : path) {
    if (status.canTransitionTo(next)) {
        System.out.println(status + " -> " + next);
        status = next;
    }
}

