    final int bit;
    Permission(int bit) { this.bit = bit; }
}

static int combine(Permission... perms) {
    int mask = 0;
    for (Permission p : perms) mask |= p.bit;
    return mask;
}

static boolean hasPermission(int mask, Permission p) { return (mask & p.bit) != 0; }

