enum SortAlgorithm {
    BUBBLE { public void sort(int[] a) {
        for (int i=0;i<a.length-1;i++) for (int j=0;j<a.length-1-i;j++)
            if (a[j]>a[j+1]) { int t=a[j]; a[j]=a[j+1]; a[j+1]=t; }
    }},
    SELECTION { public void sort(int[] a) {
        for (int i=0;i<a.length-1;i++) {
            int min=i;
            for (int j=i+1;j<a.length;j++) if (a[j]<a[min]) min=j;
            int t=a[i]; a[i]=a[min]; a[min]=t;
        }
    }},
    INSERTION { public void sort(int[] a) {
        for (int i=1;i<a.length;i++) {
            int key=a[i], j=i-1;
            while (j>=0 && a[j]>key) { a[j+1]=a[j]; j--; }
            a[j+1]=key;
        }
    }},
    MERGE_SIMPLE { public void sort(int[] a) { java.util.Arrays.sort(a); } };

    public abstract void sort(int[] arr);
}

int[] base = new int[100];
java.util.Random rnd = new java.util.Random(1);
for (int i=0;i<base.length;i++) base[i]=rnd.nextInt(1000);

for (SortAlgorithm algo : SortAlgorithm.values()) {
    int[] copy = base.clone();
    long start = System.nanoTime();
    algo.sort(copy);
    long time = System.nanoTime() - start;
    System.out.println(algo + ": " + time + " ns");
}

