    REMOVE("Usuwa element"), QUIT("Konczy program");

    final String description;
    Command(String description) { this.description = description; }

    static Command parse(String input) {
        try { return Command.valueOf(input.toUpperCase()); }
        catch (IllegalArgumentException e) { return null; }
    }
}

class CLI {
    void process(String userInput) {
        Command cmd = Command.parse(userInput);
        if (cmd == null) { System.out.println("Nieznana komenda: " + userInput); return; }
        switch (cmd) {
            case HELP -> System.out.println("Pomoc: " + cmd.description);
            case LIST -> System.out.println("Lista elementow...");
            case ADD -> System.out.println("Dodawanie...");
            case REMOVE -> System.out.println("Usuwanie...");
            case QUIT -> System.out.println("Do widzenia!");
        }
    }
}

