interface ShapeVisitor {
    double visitCircle(double r);
    double visitRect(double w, double h);
    double visitTriangle(double b, double h);
}

enum Shape {
    CIRCLE { public double accept(ShapeVisitor v, double... p) { return v.visitCircle(p[0]); } },
    RECTANGLE { public double accept(ShapeVisitor v, double... p) { return v.visitRect(p[0], p[1]); } },
    TRIANGLE { public double accept(ShapeVisitor v, double... p) { return v.visitTriangle(p[0], p[1]); } };

    public abstract double accept(ShapeVisitor v, double... params);
}

ShapeVisitor areaVisitor = new ShapeVisitor() {
    public double visitCircle(double r) { return Math.PI * r * r; }
    public double visitRect(double w, double h) { return w * h; }
    public double visitTriangle(double b, double h) { return 0.5 * b * h; }
};

System.out.println(Shape.CIRCLE.accept(areaVisitor, 5));
System.out.println(Shape.RECTANGLE.accept(areaVisitor, 4, 6));

enum DbType {
    MYSQL(3306), POSTGRESQL(5432), SQLITE(0), H2(9092);
    final int defaultPort;
    DbType(int defaultPort) { this.defaultPort = defaultPort; }
}

class DbConfig {
    DbType type; String host; int port; String user, password;
    private DbConfig() {}

    static class Builder {
        private DbType type; private String host; private int port;
        private String user, password;

        Builder(DbType type) { this.type = type; this.port = type.defaultPort; }
        Builder host(String h) { this.host = h; return this; }
        Builder credentials(String u, String p) { this.user = u; this.password = p; return this; }

        void validate() {
            if (host == null || host.isBlank()) throw new IllegalStateException("Host wymagany");
        }

        DbConfig build() {
            validate();
            DbConfig cfg = new DbConfig();
            cfg.type = type; cfg.host = host; cfg.port = port; cfg.user = user; cfg.password = password;
            return cfg;
        }
    }
}

DbConfig cfg = new DbConfig.Builder(DbType.POSTGRESQL).host("localhost").credentials("admin", "secret").build();
System.out.println(cfg.type + " " + cfg.host + ":" + cfg.port);
